def findMax(nums: list) -> int:
    if not nums:
        return 0
    max_val = nums[0]
    for val in nums[1:]:
        if val > max_val:
            max_val = val
    return max_val

problems.javaCode:
public class Solution {
    public static int findMax(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        int maxVal = nums[0];
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > maxVal) {
                maxVal = nums[i];
            }
        }
        return maxVal;
    }
}

